SELECT

FROM story s
LEFT JOIN story_category c ON s.category_id = c.id


    AND s.title LIKE CONCAT('%', #{query.keyword}, '%')


    AND s.category_id = #{query.categoryId}


    AND c.category_type = #{query.categoryType}


    AND s.status = #{query.status}


ORDER BY c.category_type, s.sort, s.id

SELECT

FROM story s
WHERE s.id = #{id}

mapper.update:
UPDATE story

  category_id = #{categoryId},
  title = #{title},
  description = #{description},
  sort = #{sort}

WHERE id = #{id}

UPDATE story

  status = #{status},
  reviewer_id = #{reviewerId},
  review_time = #{reviewTime},
  review_remark = #{reviewRemark}

WHERE id = #{id}

